package com.fashionlooks.aemcloudstarter.core.models;

import javax.annotation.PostConstruct;
import org.apache.sling.api.resource.Resource;
import org.apache.sling.models.annotations.DefaultInjectionStrategy;
import org.apache.sling.models.annotations.Model;
import org.apache.sling.models.annotations.injectorspecific.ValueMapValue;

/**
 * Example Sling Model for an authorable promotional component.
 * Copy into the core module generated by the current AEM Project Archetype.
 */
@Model(
    adaptables = Resource.class,
    defaultInjectionStrategy = DefaultInjectionStrategy.OPTIONAL
)
public class PromoModel {

    @ValueMapValue
    private String title;

    @ValueMapValue
    private String description;

    @ValueMapValue
    private String ctaLabel;

    @ValueMapValue
    private String ctaUrl;

    private boolean validCta;

    @PostConstruct
    protected void init() {
        validCta = ctaLabel != null && !ctaLabel.isBlank()
            && ctaUrl != null && !ctaUrl.isBlank();
    }

    public String getTitle() {
        return title;
    }

    public String getDescription() {
        return description;
    }

    public String getCtaLabel() {
        return ctaLabel;
    }

    public String getCtaUrl() {
        return ctaUrl;
    }

    public boolean isValidCta() {
        return validCta;
    }
}
